inline int fxOrderActionsChecks(){using namespace juce;auto owner=std::make_unique<SynthProcessor>();auto& p=*owner;p.prepareToPlay(48000,512);p.loadPreset(0);int first=p.addFx(0,1),second=p.addFx(0,5),other=p.addFx(1,3);FxPage page(p);page.setSize(1208,390);ListBox* order=nullptr;TextButton *main=nullptr,*bus1=nullptr;for(auto* c:page.getChildren()){if(c->getComponentID()=="fx-rack-order")order=dynamic_cast<ListBox*>(c);if(auto* b=dynamic_cast<TextButton*>(c)){if(b->getButtonText()=="MAIN")main=b;if(b->getButtonText()=="BUS 1")bus1=b;}}auto fail=[](const char* why){std::cerr<<"FX ORDER ACTIONS FAIL: "<<why<<"\n";return 390;};if(!order||!main||!bus1)return fail("missing list/navigation");auto button=[&](int row,String id)->Button*{if(auto* actions=order->getComponentForRowNumber(row))for(auto* c:actions->getChildren())if(c->getComponentID()==id)return dynamic_cast<Button*>(c);return nullptr;};auto click=[](Button& b){auto at=b.getLocalBounds().getCentre().toFloat();auto now=Time::getCurrentTime();MouseEvent e(Desktop::getInstance().getMainMouseSource(),at,ModifierKeys(ModifierKeys::leftButtonModifier),1,0,0,0,0,&b,&b,now,at,now,1,false);static_cast<Component&>(b).mouseDown(e);static_cast<Component&>(b).mouseUp(e);};auto* bypass=button(0,"fx-order-bypass:"+String(first));auto* remove=button(0,"fx-order-remove:"+String(first));auto* actions=order->getComponentForRowNumber(0);if(!bypass||!remove||!actions||actions->hitTest(30,15)||bypass->getRight()>=remove->getX()||remove->getRight()>actions->getWidth())return fail("layout/name drag hit testing");click(*bypass);if(p.value(fxId(first,"enabled"))!=0||p.value(fxId(second,"enabled"))!=1||p.value(fxId(other,"enabled"))!=1)return fail("bypass changed wrong instance");bool rackSynced=false;std::function<void(Component&)> visit=[&](Component& c){if(c.getComponentID()=="fx-bypass:"+String(first))if(auto* b=dynamic_cast<Button*>(&c))rackSynced=!b->getToggleState();for(auto* child:c.getChildren())visit(*child);};visit(page);if(!rackSynced)return fail("rack/sidebar bypass sync");p.set(fxId(first,"enabled"),1);if(!bypass->getToggleState())return fail("host automation sync");p.moveFxTo(second,0);main->onClick();if(!button(0,"fx-order-bypass:"+String(second)))return fail("row reuse after reorder");remove=button(0,"fx-order-remove:"+String(second));if(!remove)return fail("remove after reorder absent");click(*remove);for(auto& entry:p.rack()->entries)if(entry.slot==second)return fail("remove kept selected effect");main->onClick();if(!button(0,"fx-order-bypass:"+String(first))||p.rack()->entries.size()!=2)return fail("row reuse after removal");bus1->onClick();bypass=button(0,"fx-order-bypass:"+String(other));if(!bypass)return fail("bus sidebar actions absent");click(*bypass);if(p.value(fxId(other,"enabled"))!=0||p.value(fxId(first,"enabled"))!=1)return fail("bus isolation");std::cout<<"PASS: real sidebar button clicks, per-instance bypass/removal, rack/host synchronization, name-area drag hit testing, row reuse after reorder/removal and independent buses.\n";return 0;}
